bash -lc $'set -euo pipefail\nroot="$PWD"\nrustup update stable\nscratch=$(mktemp -d /tmp/cx-broad-work-v2.XXXXXX)\ntrap \'rm -rf "$scratch"\' EXIT\nprintf \'%s\' \'\' | base64 -d > "$scratch/probe.py"\nexport CARGO_INCREMENTAL=0 CARGO_PROFILE_DEV_DEBUG=0 CARGO_PROFILE_TEST_DEBUG=0\nexport CARGO_TARGET_DIR="$scratch/target"\nproof() {\npython3 - "$scratch/$1.jsonl" "$1" "$2" <<\'PY\'\nimport base64,gzip,json,pathlib,sys\np=pathlib.Path(sys.argv[1]);data=p.read_bytes()\nprint(json.dumps({\'kind\':\'full-proof\',\'revision\':sys.argv[2],\'code\':int(sys.argv[3]),\'gzip_base64\':base64.b64encode(gzip.compress(data)).decode()}),flush=True)\nfor line in data.decode().splitlines():\n try: row=json.loads(line)\n except ValueError: continue\n if row.get(\'kind\') in (\'configuration\',\'inventory_complete\',\'summary\'):\n  print(json.dumps({\'revision\':sys.argv[2],**row}),flush=True)\nPY\n}\ngit -C "$root" fetch origin 7cde4119547109994eb685d6ff10187ce0b846fc\ngit -C "$root" checkout --detach 7cde4119547109994eb685d6ff10187ce0b846fc --\nbefore=0\ntimeout 9000 python3 -B "$scratch/probe.py" --sha 7cde4119547109994eb685d6ff10187ce0b846fc > "$scratch/before.jsonl" 2>&1 || before=$?\nproof before "$before"\ngit -C "$root" checkout --detach 6ed614e69c79d6f88ba8bfbf9098555358ee077d --\nafter=0\ntimeout 9000 python3 -B "$scratch/probe.py" --sha 6ed614e69c79d6f88ba8bfbf9098555358ee077d > "$scratch/after.jsonl" 2>&1 || after=$?\nproof after "$after"\n[ "$before" -eq 0 ] && [ "$after" -eq 0 ]'
